def scope_text(scope: str | None) -> str:
    """The prompt's line for a planner limited to one module, which runs beside planners of other modules."""
    if not scope:
        return ""
    return (f"\n- This task is limited to {scope}, because planners of other modules may be working at the same "
            f"time. Change {scope}'s folder in the plans folder, the files outside it that {scope} owns, and "
            "additions to the shared project files, such as a glossary entry. If the task needs another module's "
            "files, or an interface in the module list that another module provides or uses, end with "
            "`BLOCKED: needs <MODULE>'s files`, saying which change and what it must deliver; the lead then gives "
            "the task to a planner for the whole project.")


def module_name_arg(value: str) -> str:
    if not re.fullmatch(r"[A-Za-z0-9_-]+", value):
        raise argparse.ArgumentTypeError(f"{value!r} isn't a module name")
    return value


def module_args(module: str | None) -> list[str]:
    """The `--module` flag for a `plan` command limited to one module, which lets it run beside planners of other
    modules."""
    return ["--module", module] if module else []


def kind_args(kind: str | None) -> list[str]:
    """The `--kind` flag for a `plan` command, left out when the script can tell the kind from the project."""
    return ["--kind", kind] if kind else []


TURN_TIMEOUT_HOURS = 2.0  # the --turn-timeout-hours a command gets when the lead names none


def plan_flags(a: argparse.Namespace, on: str | None = None) -> list[str]:
    """The flags the lead gave this `plan`, other than its task and module, for a `next` that gives a planner the task
    again: its kind, host, model, effort, turn limit and `--one-step`. A lead runs `next` as it is printed, so a flag
    left out changes what runs: without `--one-step`, a first plan would carry on into design reviews before the user
    has seen it. A step of a longer `plan` gets `--one-step` from that command, not from the lead, so its `next`
    leaves it out, as the lead's own command did. `on` names another host for the turn, which drops the model, since
    one host's model doesn't run on another."""
    host = on or getattr(a, "host", None)
    out = [*kind_args(getattr(a, "kind", None)), *(["--host", host] if host else [])]
    if getattr(a, "model", None) and not on:
        out += ["--model", a.model]
    if getattr(a, "effort", None):
        out += ["--effort", a.effort]
    hours = getattr(a, "turn_timeout_hours", None)
    if hours is not None and hours != TURN_TIMEOUT_HOURS:
        out += ["--turn-timeout-hours", f"{hours:g}"]
    if getattr(a, "one_step", False) and not STEPS_PARENT:
        out.append("--one-step")
    return out


def default_kind(tree: Path, prof: dict) -> str:
    """The kind of task of a `plan` with no `--kind`: a new project when there is no module list yet, otherwise a module."""
    path = tree / project_file(prof, "architecture")
    return "module" if path.exists() and module_table(path.read_text(encoding="utf-8", errors="replace")) else "project"


def kind_text(kind: str, skill: str = "planner") -> str:
    """The instructions for a kind of task, from its file in the skill's tasks/ folder, with links made absolute so
    they work in a prompt. Planning a new project includes planning its first modules, so it carries the module file
    too. The reviewer's kinds are `work-package` and `design`."""
    parts = []
    for name in ("project", "module") if (skill, kind) == ("planner", "project") else (kind,):
        path = SKILLS / skill / "tasks" / f"{name}.md"
        text = path.read_text(encoding="utf-8").strip()
        parts.append(RELATIVE_LINK.sub(lambda m: f"]({os.path.normpath(path.parent / m.group(1))}{m.group(2) or ''})", text))
    return "\n\n".join(parts)


